from pathlib import Path
import zipfile

out_dir = Path("/mnt/data/ecg_icon_assets")
out_dir.mkdir(exist_ok=True)

common_style = """
<style>
  .stroke { fill: none; stroke: #123f73; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; }
  .thin { fill: none; stroke: #123f73; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  .accent { fill: rgba(18, 63, 115, 0.08); stroke: #123f73; stroke-width: 2.4; stroke-dasharray: 5 4; }
  .text { fill: #1f2937; font-family: Arial, Helvetica, sans-serif; font-size: 18px; }
  .small { fill: #1f2937; font-family: Arial, Helvetica, sans-serif; font-size: 14px; }
</style>
"""

pr_svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="360" height="220" viewBox="0 0 360 220">
{common_style}
  <rect width="360" height="220" fill="white" opacity="0"/>
  <!-- ECG waveform: P wave, QRS complex, T wave -->
  <path class="stroke" d="
    M 35 110
    L 70 110
    C 78 110, 82 92, 90 92
    C 98 92, 102 110, 110 110
    L 135 110
    L 150 72
    L 166 150
    L 182 52
    L 198 110
    L 235 110
    C 250 110, 258 94, 272 94
    C 286 94, 294 110, 310 110
    L 330 110" />

  <!-- labels -->
  <text class="small" x="87" y="82" text-anchor="middle">P</text>
  <text class="small" x="181" y="42" text-anchor="middle">R</text>
  <text class="small" x="273" y="84" text-anchor="middle">T</text>

  <!-- PR interval bracket: P-wave onset to QRS onset, not to R peak -->
  <line class="thin" x1="70" y1="172" x2="150" y2="172"/>
  <path class="thin" d="M 70 164 L 70 180"/>
  <path class="thin" d="M 150 164 L 150 180"/>
  <path class="thin" d="M 78 172 L 92 164"/>
  <path class="thin" d="M 78 172 L 92 180"/>
  <path class="thin" d="M 142 172 L 128 164"/>
  <path class="thin" d="M 142 172 L 128 180"/>

  <text class="text" x="110" y="204" text-anchor="middle">PR interval</text>
</svg>
'''

rate_svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="360" height="220" viewBox="0 0 360 220">
{common_style}
  <rect width="360" height="220" fill="white" opacity="0"/>

  <!-- repeated R peaks / rhythm strip -->
  <path class="stroke" d="
    M 35 115
    L 55 115 L 65 74 L 75 142 L 85 115
    L 120 115 L 130 74 L 140 142 L 150 115
    L 190 115 L 200 74 L 210 142 L 220 115
    L 270 115 L 280 74 L 290 142 L 300 115
    L 330 115" />

  <!-- RR interval brackets -->
  <line class="thin" x1="65" y1="174" x2="130" y2="174"/>
  <path class="thin" d="M 65 166 L 65 182"/>
  <path class="thin" d="M 130 166 L 130 182"/>
  <line class="thin" x1="200" y1="174" x2="280" y2="174"/>
  <path class="thin" d="M 200 166 L 200 182"/>
  <path class="thin" d="M 280 166 L 280 182"/>

  <!-- short vs long interval cue -->
  <text class="small" x="98" y="201" text-anchor="middle">RR</text>
  <text class="small" x="240" y="201" text-anchor="middle">RR</text>
  <text class="text" x="180" y="34" text-anchor="middle">rate / rhythm</text>
</svg>
'''

html = f'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>ECG Evidence Form Icons</title>
<style>
  body {{
    margin: 0;
    padding: 32px;
    font-family: Arial, Helvetica, sans-serif;
    color: #1f2937;
    background: #ffffff;
  }}
  .wrap {{
    display: flex;
    gap: 36px;
    align-items: flex-start;
  }}
  .card {{
    border: 1px solid #d5dce6;
    border-radius: 10px;
    padding: 18px;
    width: 360px;
  }}
  h2 {{
    font-size: 18px;
    margin: 0 0 12px 0;
    color: #123f73;
  }}
  p {{
    font-size: 13px;
    line-height: 1.4;
    margin: 10px 0 0;
  }}
</style>
</head>
<body>
  <div class="wrap">
    <div class="card">
      <h2>PR timing</h2>
      {pr_svg}
      <p>Bracket marks PR interval from P-wave onset to QRS onset, not to the R peak.</p>
    </div>
    <div class="card">
      <h2>Rate / rhythm</h2>
      {rate_svg}
      <p>Repeated R peaks and RR intervals represent global rate/rhythm evidence.</p>
    </div>
  </div>
</body>
</html>
'''

(out_dir / "pr_timing_icon.svg").write_text(pr_svg, encoding="utf-8")
(out_dir / "rate_rhythm_icon.svg").write_text(rate_svg, encoding="utf-8")
(out_dir / "ecg_evidence_icons_preview.html").write_text(html, encoding="utf-8")

zip_path = Path("/mnt/data/ecg_evidence_icons_for_figma.zip")
with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
    for p in out_dir.iterdir():
        z.write(p, arcname=p.name)

print(f"Created files:\n- {out_dir / 'pr_timing_icon.svg'}\n- {out_dir / 'rate_rhythm_icon.svg'}\n- {out_dir / 'ecg_evidence_icons_preview.html'}\n- {zip_path}")

