    front = f'<polygon class="blue-fill" points="{x},{y} {x+w},{y+dy} {x+w},{y+h+dy} {x},{y+h}" />'
    side = f'<polygon class="blue-fill" points="{x+w},{y+dy} {x+w+dx},{y} {x+w+dx},{y+h} {x+w},{y+h+dy}" style="fill:#5f8dce;" />'
    top = f'<polygon class="blue-fill" points="{x},{y} {x+w},{y+dy} {x+w+dx},{y} {x+dx},{y+dy}" style="fill:#9fbee9;" />'
    return front + top + side

